      <section v-if="selected" class="split-detail review-detail"><div class="detail-heading"><div><span class="status-pill" :class="selected.levelClass"><span class="dot"></span>{{ selected.level }}</span><h2>{{ selected.title }}</h2><p>{{ selected.id }} · 创建于 {{ selected.createdAt }} · 规则版本 {{ selected.ruleVersion }}</p></div><el-button :icon="MoreHorizontal" circle /></div><div class="review-patient"><div class="review-avatar">{{ selected.patient.slice(-1) }}</div><div><strong>{{ selected.patient }}</strong><span>男 · 68岁 · {{ selected.encounter }} · {{ selected.department }}</span></div><el-button size="small" @click="$router.push('/doctor/workbench/E004')">打开患者决策台</el-button></div><el-tabs v-model="detailTab" class="detail-tabs"><el-tab-pane label="风险与双方方案" name="risk"><div class="risk-comparison"><section><span>当前科室拟用方案</span><strong>头孢曲松 + 阿奇霉素</strong><p>呼吸内科 · 陈医生 · 待生成草稿</p></section><div class="conflict-axis"><GitCompareArrows :size="19" /><span>重复用药</span></div><section><span>其他科室有效医嘱</span><strong>阿奇霉素</strong><p>心内科 · 李医生 · 08-03 07:05 生效</p></section></div><div class="rule-hit"><ShieldAlert :size="18" /><div><strong>HR-XDEPT-001 · 跨科室当前有效用药冲突</strong><p>同一患者多个科室存在当前有效药物，新方案提交前必须复核；系统不得自动停止其他科室医嘱。</p><button>查看命中事实 ORD-CARD-004 <ExternalLink :size="12" /></button></div></div><div class="evidence-brief"><div class="section-caption"><h3>相关证据与规则依据</h3><span>2 条</span></div><article><BookOpenCheck :size="16" /><div><strong>CAP 演示证据集：监测要求</strong><p>第4页 · 监测项目 · 表2</p></div><el-button size="small">查看定位</el-button></article><article><GitBranch :size="16" /><div><strong>跨科室冲突规则</strong><p>v2026.08 · 已发布演示规则</p></div><el-button size="small">查看版本</el-button></article></div></el-tab-pane><el-tab-pane label="沟通与处理记录" name="communication"><div class="communication-list"><article v-for="entry in communications" :key="entry.time"><span>{{ entry.actor.slice(0,1) }}</span><div><div><strong>{{ entry.actor }}</strong><time>{{ entry.time }}</time></div><p>{{ entry.text }}